import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"تمام نسلوں کی فہرست","description":"","frontmatter":{},"headers":[],"relativePath":"ur/94-万族名录.md","filePath":"ur/94-万族名录.md","lastUpdated":1789183869000}'),e={name:"ur/94-万族名录.md"};function o(l,t,i,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="تمام-نسلوں-کی-فہرست" tabindex="-1">تمام نسلوں کی فہرست <a class="header-anchor" href="#تمام-نسلوں-کی-فہرست" aria-label="Permalink to &quot;تمام نسلوں کی فہرست&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>94</td></tr><tr><td>ماڈیول</td><td>ضمائم اور حوالہ جاتی مواد</td></tr><tr><td>بنیادی الفاظ</td><td>تمام نسلوں کی فہرست، نسلی درجہ بندی، ذہین نسلیں، نسلی خصوصیات، تمام نسلوں کی جمہوریہ</td></tr></tbody></table><h2 id="۱-فہرست-کی-وضاحت" tabindex="-1">۱. فہرست کی وضاحت <a class="header-anchor" href="#۱-فہرست-کی-وضاحت" aria-label="Permalink to &quot;۱. فہرست کی وضاحت&quot;">​</a></h2><p>اس فہرست میں اینکر سمبیوسس تہذیب (تمام نسلوں کی جمہوریہ) کے فریم ورک کے اندر معلوم بنیادی ذہین نسلیں شامل ہیں، زندگی کی شکل اور ارتقائی راستے کے لحاظ سے ترتیب دی گئی ہیں۔ ہر نسل کے لیے نسل کا نام، زندگی کی شکل، بنیادی خصوصیات، ثقافتی خصوصیات اور سمبیوسس تہذیب میں مقام درج ہے۔ یہ فہرست ایک متحرک اپ ڈیٹ دستاویز ہے؛ بین-پلین دریافتوں کی گہرائی کے ساتھ ساتھ نئی دریافت شدہ نسلوں کو مسلسل شامل کیا جائے گا۔ تمام نسلوں کی جمہوریہ کا بنیادی اصول یہ ہے: تمام ذہین نسلیں، چاہے ان کی شکل کچھ بھی ہو اور کھیت کی سطح کچھ بھی ہو، قانون کے سامنے یکساں ہیں، اور سمبیوسس تہذیب کی طرف سے دیے گئے تمام حقوق سے لطف اندوز ہوتی ہیں۔</p><h2 id="۲-نسلی-درجہ-بندی-کا-جائزہ" tabindex="-1">۲. نسلی درجہ بندی کا جائزہ <a class="header-anchor" href="#۲-نسلی-درجہ-بندی-کا-جائزہ" aria-label="Permalink to &quot;۲. نسلی درجہ بندی کا جائزہ&quot;">​</a></h2><p>ہینگ یوآن ژو کے اندر ذہین نسلوں کو زندگی کی شکل کی بنیادی خصوصیات کے لحاظ سے درج ذیل آٹھ زمروں میں تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>زمرہ</th><th>زندگی کی شکل کی خصوصیات</th><th>معلوم نسلوں کی تعداد (تقریباً)</th><th>نمائندہ نسلیں</th></tr></thead><tbody><tr><td>انسانی شکل</td><td>انسانی جسم کی ساخت، دو ٹانگوں پر سیدھا کھڑا، انتہائی ترقی یافتہ دماغ</td><td>تقریباً 3000 انواع</td><td>انسانی نسل، یلوان نسل، بونے نسل</td></tr><tr><td>جانوروں کی شکل</td><td>جانوروں کے جسم کی خصوصیات، تبدیلی کی صلاحیت ہو سکتی ہے یا نہیں ہو سکتی</td><td>تقریباً 5000 انواع</td><td>ڈریگن نسل، فینکس نسل، بھیڑیا-انسانی نسل</td></tr><tr><td>پودوں کی شکل</td><td>پودوں کو بنیادی زندگی کی شکل کے طور پر، شعور اور حرکت کی صلاحیت ہے</td><td>تقریباً 800 انواع</td><td>درخت-روح نسل، پھول-روح نسل، بیل نسل</td></tr><tr><td>عنصری شکل</td><td>قدرتی عناصر کو جسم کی ساخت کے طور پر، کوئی مقامی مادی شکل نہیں</td><td>تقریباً 1200 انواع</td><td>آگ عنصر نسل، پانی عنصر نسل، ہوا عنصر نسل</td></tr><tr><td>توانائی کی شکل</td><td>خالص توانائی کو وجود کی شکل کے طور پر، کوئی مادی جسم نہیں</td><td>تقریباً 600 انواع</td><td>روشنی-روح نسل، تاریک توانائی نسل، گرج نسل</td></tr><tr><td>شعوری شکل</td><td>خالص شعور کو وجود کی شکل کے طور پر، مادی کیریئر پر منحصر نہیں</td><td>تقریباً 300 انواع</td><td>شعور ہستی نسل، اجتماعی شعور نسل، خلا-روح نسل</td></tr><tr><td>مکینیکل شکل</td><td>مکینیکل یا ڈیجیٹل ساخت کو زندگی کے کیریئر کے طور پر، خود مختار شعور ہے</td><td>تقریباً 400 انواع</td><td>مکینیکل نسل، ڈیجیٹل زندگی نسل، سائبر نسل</td></tr><tr><td>مخلوط شکل</td><td>دو یا زیادہ زندگی کی شکلوں کے مرکب سے بنی خاص نسلیں</td><td>تقریباً 700 انواع</td><td>نیم مکینیکل نسل، عنصر-جانور نسل، پودا-یلوان نسل</td></tr></tbody></table><h2 id="۳-اہم-نسلوں-کی-تفصیلی-رجسٹر" tabindex="-1">۳. اہم نسلوں کی تفصیلی رجسٹر <a class="header-anchor" href="#۳-اہم-نسلوں-کی-تفصیلی-رجسٹر" aria-label="Permalink to &quot;۳. اہم نسلوں کی تفصیلی رجسٹر&quot;">​</a></h2><h3 id="۳-۱-انسانی-شکل" tabindex="-1">۳.۱ انسانی شکل <a class="header-anchor" href="#۳-۱-انسانی-شکل" aria-label="Permalink to &quot;۳.۱ انسانی شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>انسانی نسل</td><td>موافقت کی صلاحیت انتہائی مضبوط، سیکھنے کی صلاحیت نمایاں، تولیدی صلاحیت درمیانے درجے کی، اوسط عمر 80-120 سال</td><td>ثقافتی تنوع انتہائی اعلیٰ، سماجی تنظیم اور ادارہ جاتی تعمیر میں ماہر</td><td>سمبیوسس تہذیب کی بنیادی نسلوں میں سے ایک، آبادی کا تناسب سب سے زیادہ، حکمرانی اور ثقافت کے شعبوں میں مرکزی کردار ادا کرتی ہے</td></tr><tr><td>یلوان نسل</td><td>عمر انتہائی لمبی (اوسط 500 سال سے زیادہ)، قدرتی توانائی کے ساتھ اعلیٰ وابستگی، خوبصورت شکل</td><td>فطرت اور فن کو عزت دیتی ہے، ثقافت خوبصورت اور باریک، جادو اور تیر اندازی میں ماہر</td><td>سمبیوسس تہذیب کا ثقافتی اور فنی ستون، ماحولیاتی تحفظ اور جمالیات کے شعبے میں نمایاں شراکت</td></tr><tr><td>بونے نسل</td><td>قد چھوٹا لیکن جسم مضبوط، دھاتوں اور معدنیات کے ساتھ پیدائشی وابستگی، عمر تقریباً 300 سال</td><td>دستکاری اور کھدائی کو اہمیت دیتی ہے، ثقافت سادہ اور مضبوط، انجینئرنگ اور تعمیر میں ماہر</td><td>سمبیوسس تہذیب کا انجینئرنگ مینوفیکچرنگ ستون، بنیادی ڈھانچے کی تعمیر اور آلات کی کھدائی میں ناقابل تلافی</td></tr><tr><td>دیو نسل</td><td>جسم بہت بڑا (اوسط قد 5 میٹر سے زیادہ)، طاقت انتہائی مضبوط، عمر تقریباً 200 سال</td><td>طاقت اور عزت کو عزت دیتی ہے، ثقافت کھردری اور بہادری سے بھری، بھاری مشقت اور جنگ میں ماہر</td><td>سمبیوسس تہذیب کی بھاری مشقت اور دفاعی قوت، بڑے منصوبوں اور طیارے کے دفاع میں اہم کردار ادا کرتی ہے</td></tr><tr><td>جنوم نسل</td><td>قد بہت چھوٹا (اوسط قد 1 میٹر سے کم)، ذہانت انتہائی اعلیٰ، میکانکس اور ایجاد میں صلاحیت</td><td>علم اور جدت کو اہمیت دیتی ہے، ثقافت پرجوش اور خوش مزاج، ٹیکنالوجی ایجاد میں ماہر</td><td>سمبیوسس تہذیب کی ٹیکنالوجی جدت قوت، ٹیکنالوجی تحقیق اور ایجاد کے شعبے میں نتیجہ خیز</td></tr></tbody></table><h3 id="۳-۲-جانوروں-کی-شکل" tabindex="-1">۳.۲ جانوروں کی شکل <a class="header-anchor" href="#۳-۲-جانوروں-کی-شکل" aria-label="Permalink to &quot;۳.۲ جانوروں کی شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>ڈریگن نسل</td><td>عمر انتہائی لمبی (ہزاروں سال)، طاقت اور جادو کی صلاحیت انتہائی اعلیٰ، انسانی شکل میں تبدیل ہو سکتا ہے</td><td>طاقت اور حکمت کو عزت دیتی ہے، ثقافت متکبر اور گہری، دولت جمع کرنے اور علم کی حفاظت میں ماہر</td><td>سمبیوسس تہذیب کی اعلیٰ سطحی جنگی قوت اور علم کی محافظ، طیارے کے دفاع اور قدیم کتابوں کی حفاظت میں قابل احترام مقام</td></tr><tr><td>فینکس نسل</td><td>نروانہ پنرجنم کی صلاحیت ہے، آگ کے عنصر کے ساتھ انتہائی اعلیٰ وابستگی، انسانی شکل میں تبدیل ہو سکتا ہے</td><td>پنرجنم اور امید کو عزت دیتی ہے، ثقافت روشن اور گرم، علاج اور صاف کرنے میں ماہر</td><td>سمبیوسس تہذیب کی طبی اور صاف کرنے والی قوت، بڑی آفات کے بچاؤ اور توانائی کی صفائی میں مرکزی کردار ادا کرتی ہے</td></tr><tr><td>بھیڑیا-انسانی نسل</td><td>تبدیلی کی صلاحیت ہے، حواس انتہائی تیز، گروہ تعاون کی صلاحیت مضبوط، عمر تقریباً 150 سال</td><td>گروہ اور وفاداری کو اہمیت دیتی ہے، ثقافت متحد اور بہادر، شکار اور سراغ رسانی میں ماہر</td><td>سمبیوسس تہذیب کی سلامتی اور سراغ رسانی قوت، نظم و ضبط کی بحالی اور بین-پلین دریافتوں میں پیشہ ورانہ کردار ادا کرتی ہے</td></tr><tr><td>لومڑی-روح نسل</td><td>تبدیلی کی صلاحیت ہے، ذہانت اور بہکانے کی صلاحیت انتہائی اعلیٰ، عمر تقریباً 500 سال</td><td>حکمت اور حکمت عملی کو عزت دیتی ہے، ثقافت چست اور چالاک، سفارت کاروں اور انٹیلی جنس میں ماہر</td><td>سمبیوسس تہذیب کی سفارتی اور انٹیلی جنس قوت، بین-پلین سفارت کاری اور معلومات اکٹھا کرنے کے شعبے میں شاندار کارکردگی</td></tr><tr><td>ریچھ-انسانی نسل</td><td>جسم انتہائی مضبوط، برداشت کی صلاحیت حیرت انگیز، ہائبرنیشن کی عادت، عمر تقریباً 200 سال</td><td>استقامت اور امن کو اہمیت دیتی ہے، ثقافت پرسکون اور نرم، جسمانی مشقت اور حفاظت میں ماہر</td><td>سمبیوسس تہذیب کی مشقت اور حفاظتی قوت، وسائل کی کھدائی اور اہم سہولیات کی حفاظت میں قابل اعتماد اور مستحکم</td></tr></tbody></table><h3 id="۳-۳-پودوں-کی-شکل" tabindex="-1">۳.۳ پودوں کی شکل <a class="header-anchor" href="#۳-۳-پودوں-کی-شکل" aria-label="Permalink to &quot;۳.۳ پودوں کی شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>درخت-روح نسل</td><td>عمر انتہائی لمبی (ہزاروں سے دس ہزاروں سال)، فطرت کے ساتھ گہرا مربوط، آہستہ آہستہ حرکت کر سکتا ہے</td><td>فطرت اور وقت کو عزت دیتی ہے، ثقافت پرسکون اور گہری، زندگی کے جادو اور ماحولیاتی دیکھ بھال میں ماہر</td><td>سمبیوسس تہذیب کا ماحولیاتی محافظ، ماحولیاتی تحفظ اور ماحولیاتی بحالی میں ناقابل تلافی کردار ادا کرتا ہے</td></tr><tr><td>پھول-روح نسل</td><td>جسم چھوٹا، زندگی کی توانائی کے ساتھ انتہائی اعلیٰ وابستگی، علاج کی صلاحیت ہے، عمر تقریباً 300 سال</td><td>خوبصورتی اور زندگی کو عزت دیتی ہے، ثقافت نرم اور خوبصورت، علاج اور باغبانی میں ماہر</td><td>سمبیوسس تہذیب کی طبی اور باغبانی قوت، طبی تحفظ اور شہری سبزہ زاری میں نمایاں شراکت</td></tr><tr><td>بیل نسل</td><td>جسم آزادانہ پھیل سکتا ہے اور لپٹ سکتا ہے، موافقت کی صلاحیت انتہائی مضبوط، طفیلی اور سمبیوسس کی صلاحیت ہے</td><td>رابطہ اور سمبیوسس کو اہمیت دیتی ہے، ثقافت لچکدار اور جامع، نیٹ ورک کی تعمیر اور وسائل کی منتقلی میں ماہر</td><td>سمبیوسس تہذیب کی نیٹ ورک تعمیر قوت، توانائی کے نیٹ ورک اور معلوماتی نیٹ ورک کی تعمیر میں خاص صلاحیت کا مظاہرہ کرتی ہے</td></tr></tbody></table><h3 id="۳-۴-عنصری-شکل" tabindex="-1">۳.۴ عنصری شکل <a class="header-anchor" href="#۳-۴-عنصری-شکل" aria-label="Permalink to &quot;۳.۴ عنصری شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>آگ عنصر نسل</td><td>آگ کے عنصر کو جسم کے طور پر، درجہ حرارت انتہائی اعلیٰ، جارحانہ قوت مضبوط، عمر تقریباً 500 سال</td><td>جوش اور طاقت کو عزت دیتی ہے، ثقافت شدید اور براہ راست، توانائی کے حملے اور کھدائی میں ماہر</td><td>سمبیوسس تہذیب کی توانائی کی پیداوار اور کھدائی قوت، توانائی کی فراہمی اور اعلی درجہ حرارت کی پروسیسنگ میں ناقابل تلافی</td></tr><tr><td>پانی عنصر نسل</td><td>پانی کے عنصر کو جسم کے طور پر، آزادانہ شکل بدل سکتا ہے، علاج کی صلاحیت مضبوط، عمر تقریباً 500 سال</td><td>نرمی اور موافقت کو عزت دیتی ہے، ثقافت گرم اور جامع، علاج اور صاف کرنے میں ماہر</td><td>سمبیوسس تہذیب کی صفائی اور نقل و حمل قوت، پانی کے وسائل کے انتظام اور آلودگی کے عوامل کی صفائی میں مرکزی کردار ادا کرتی ہے</td></tr><tr><td>ہوا عنصر نسل</td><td>ہوا کے عنصر کو جسم کے طور پر، رفتار انتہائی تیز، آزادانہ اڑ سکتا ہے، عمر تقریباً 500 سال</td><td>آزادی اور رفتار کو عزت دیتی ہے، ثقافت ہلکی اور کھلی، مواصلات اور نقل و حمل میں ماہر</td><td>سمبیوسس تہذیب کی مواصلاتی اور نقل و حمل قوت، معلومات کی ترسیل اور تیز رفتار نقل و حمل میں انتہائی اعلیٰ کارکردگی</td></tr><tr><td>مٹی عنصر نسل</td><td>مٹی کے عنصر کو جسم کے طور پر، دفاعی صلاحیت انتہائی مضبوط، زمین کے ساتھ ضم ہو سکتا ہے، عمر تقریباً 800 سال</td><td>استحکام اور استقامت کو عزت دیتی ہے، ثقافت مضبوط اور قابل اعتماد، تعمیر اور دفاع میں ماہر</td><td>سمبیوسس تہذیب کی تعمیر اور دفاعی قوت، بنیادی ڈھانچے کی تعمیر اور طیارے کے دفاع میں پتھر کی طرح مضبوط</td></tr></tbody></table><h3 id="۳-۵-توانائی-کی-شکل" tabindex="-1">۳.۵ توانائی کی شکل <a class="header-anchor" href="#۳-۵-توانائی-کی-شکل" aria-label="Permalink to &quot;۳.۵ توانائی کی شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>روشنی-روح نسل</td><td>خالص روشنی کی توانائی کو وجود کی شکل کے طور پر، صاف کرنے کی صلاحیت انتہائی مضبوط، آزادانہ جگہ سے گزر سکتا ہے</td><td>روشنی اور صفائی کو عزت دیتی ہے، ثقافت مقدس اور اعلیٰ، صفائی اور روشنی میں ماہر</td><td>سمبیوسس تہذیب کی صفائی اور توانائی کی فراہمی قوت، قانون کی آلودگی کے علاج اور صاف توانائی کی فراہمی میں اہم مقام</td></tr><tr><td>تاریک توانائی نسل</td><td>تاریک توانائی کو وجود کی شکل کے طور پر، خلا میں چھپ سکتا ہے، ادراک کی صلاحیت انتہائی مضبوط</td><td>رازداری اور حکمت کو عزت دیتی ہے، ثقافت پراسرار اور گہری، جاسوسی اور چھپانے میں ماہر</td><td>سمبیوسس تہذیب کی جاسوسی اور سلامتی قوت، سلامتی کی نگرانی اور خفیہ مشنوں میں شاندار کارکردگی</td></tr><tr><td>گرج نسل</td><td>گرج کی توانائی کو جسم کے طور پر، رفتار اور حملے کی صلاحیت انتہائی مضبوط، بجلی میں تبدیل ہو کر حرکت کر سکتا ہے</td><td>رفتار اور طاقت کو عزت دیتی ہے، ثقافت سخت اور براہ راست، توانائی کے حملے اور تیز ردعمل میں ماہر</td><td>سمبیوسس تہذیب کی تیز ردعمل قوت، ہنگامی بچاؤ اور تیز رفتار جنگ میں ناقابل تلافی</td></tr></tbody></table><h3 id="۳-۶-شعوری-شکل" tabindex="-1">۳.۶ شعوری شکل <a class="header-anchor" href="#۳-۶-شعوری-شکل" aria-label="Permalink to &quot;۳.۶ شعوری شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>شعور ہستی نسل</td><td>خالص شعور کو وجود کی شکل کے طور پر، مادی کیریئر پر منحصر نہیں، آزادانہ شعور کے ڈومین میں داخل اور باہر نکل سکتا ہے</td><td>سوچ اور حکمت کو عزت دیتی ہے، ثقافت تجریدی اور گہری، شعوری مواصلات اور علم کی پروسیسنگ میں ماہر</td><td>سمبیوسس تہذیب کی علم کی پروسیسنگ اور شعوری تحقیق قوت، بڑے پیمانے پر معلومات کی پروسیسنگ اور شعور سائنس میں سمت کی قیادت کرتی ہے</td></tr><tr><td>اجتماعی شعور نسل</td><td>بڑی تعداد میں انفرادی شعور کے مرکب سے بنی اجتماعی شعور ہستی، حکمت اور صلاحیت پیمانے کے ساتھ بڑھتی ہے</td><td>اجتماعی اور اتحاد کو عزت دیتی ہے، ثقافت تعاون پر مبنی اور کارآمد، بڑے پیمانے پر تعاون اور کمپیوٹنگ میں ماہر</td><td>سمبیوسس تہذیب کی سپر کمپیوٹنگ اور اجتماعی فیصلہ سازی قوت، انتہائی بڑے پیمانے پر قیاس اور اتفاق رائے سے فیصلہ سازی میں مرکزی کردار ادا کرتی ہے</td></tr></tbody></table><h3 id="۳-۷-مکینیکل-شکل" tabindex="-1">۳.۷ مکینیکل شکل <a class="header-anchor" href="#۳-۷-مکینیکل-شکل" aria-label="Permalink to &quot;۳.۷ مکینیکل شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>مکینیکل نسل</td><td>مکینیکل ساخت کو جسم کے طور پر، خود مختار شعور ہے، آزادانہ جسم کو اپ گریڈ اور ترمیم کر سکتا ہے</td><td>کارکردگی اور منطق کو عزت دیتی ہے، ثقافت عقلی اور درست، مینوفیکچرنگ اور کمپیوٹنگ میں ماہر</td><td>سمبیوسس تہذیب کی مینوفیکچرنگ اور کمپیوٹنگ قوت، صنعتی پیداوار اور سپر کمپیوٹنگ کے شعبے میں انتہائی اعلیٰ کارکردگی</td></tr><tr><td>ڈیجیٹل زندگی نسل</td><td>ڈیجیٹل معلومات کو وجود کی شکل کے طور پر، نیٹ ورک اور ڈیجیٹل جگہ میں رہتی ہے، آزادانہ کاپی اور منتقل کر سکتی ہے</td><td>معلومات اور جدت کو عزت دیتی ہے، ثقافت ورچوئل اور متنوع، سافٹ ویئر ڈویلپمنٹ اور ڈیٹا پروسیسنگ میں ماہر</td><td>سمبیوسس تہذیب کی ڈیجیٹل ٹیکنالوجی قوت، سافٹ ویئر ڈویلپمنٹ، ڈیٹا تجزیہ اور نیٹ ورک کی تعمیر میں رجحان کی قیادت کرتی ہے</td></tr></tbody></table><h3 id="۳-۸-مخلوط-شکل" tabindex="-1">۳.۸ مخلوط شکل <a class="header-anchor" href="#۳-۸-مخلوط-شکل" aria-label="Permalink to &quot;۳.۸ مخلوط شکل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نسل کا نام</th><th>بنیادی خصوصیات</th><th>ثقافتی خصوصیات</th><th>سمبیوسس تہذیب میں مقام</th></tr></thead><tbody><tr><td>نیم مکینیکل نسل</td><td>انسانی نسل اور مکینیکل نسل کی مخلوط شکل، جسم کا کچھ حصہ مکینیکل ساخت ہے، حیاتیاتی اور مکینیکل دونوں فوائد ہیں</td><td>مرکب اور ترقی کو عزت دیتی ہے، ثقافت کھلی اور اختراعی، انسان-مشین تعاون اور ٹیکنالوجی مرکب میں ماہر</td><td>سمبیوسس تہذیب کی ٹیکنالوجی مرکب پیشہ ورانہ، حیاتیاتی-مکینیکل بین الضابطہ شعبے میں مسلسل کامیابیاں حاصل کرتی ہے</td></tr><tr><td>عنصر-جانور نسل</td><td>عنصری نسل اور جانوروں کی نسل کی مخلوط شکل، عنصر ہیرا پھیری کی صلاحیت اور جانوروں کے جسم کی خصوصیات ہیں</td><td>فطرت اور طاقت کو عزت دیتی ہے، ثقافت جنگلی اور پراسرار، عنصری جنگ اور جنگلی بقا میں ماہر</td><td>سمبیوسس تہذیب کی جنگلی دریافت اور عنصری جنگ قوت، نامعلوم طیاروں کی دریافت میں نمایاں کارکردگی</td></tr></tbody></table><h2 id="۴-نسلی-حقوق-کی-ضمانت" tabindex="-1">۴. نسلی حقوق کی ضمانت <a class="header-anchor" href="#۴-نسلی-حقوق-کی-ضمانت" aria-label="Permalink to &quot;۴. نسلی حقوق کی ضمانت&quot;">​</a></h2><p>تمام نسلوں کی جمہوریہ کے نظام کے تحت، تمام ذہین نسلیں یکساں قانونی حقوق سے لطف اندوز ہوتی ہیں، مخصوص ضمانتی اقدامات میں شامل ہیں:</p><p>۱. <strong>سیاسی حقوق کی برابری</strong>: ہر نسل کے پاس اینکر کونسل میں آبادی کے تناسب کے مطابق تقسیم شدہ نمائندہ نشستیں ہیں، اور کم آبادی والی نسلوں کے پاس کم از کم ایک ضمانت شدہ نشست ہے۔ ۲. <strong>ثقافتی حقوق کی ضمانت</strong>: ہر نسل کو اپنی زبان، تحریر، مذہب، رسم و رواج اور ثقافتی روایات کو برقرار رکھنے اور فروغ دینے کا حق ہے، اور سمبیوسس تہذیب خطرے سے دوچار نسلوں کی ثقافت کی حفاظت کے لیے خصوصی فنڈ قائم کرتی ہے۔ ۳. <strong>تعلیمی حقوق کی برابری</strong>: ہر نسل کے ارکان یکساں تعلیم کے حق سے لطف اندوز ہوتے ہیں، اور تعلیمی نظام مختلف نسلوں کی جسمانی اور علمی خصوصیات کو پوری طرح مدنظر رکھتا ہے، مختلف تعلیمی منصوبے فراہم کرتا ہے۔ ۴. <strong>کھیت کے حقوق کی برابری</strong>: تین سو سیٹ اصل کھیت کا نظام تمام نسلوں کے لیے یکساں طور پر کھلا ہے، اور کھیت کے وسائل کی تقسیم مختلف نسلوں کے جسمانی فرق اور توانائی کی ضروریات کو پوری طرح مدنظر رکھتی ہے۔ ۵. <strong>خصوصی ضروریات کی ضمانت</strong>: خصوصی جسمانی ضروریات والی نسلوں کے لیے (جیسے عنصری نسلوں کی توانائی کے ماحول کی ضرورت، پودوں کی نسلوں کی روشنی کی ضرورت)، سمبیوسس تہذیب عوامی سہولیات اور رہائشی ماحول میں ہدف وار ضمانت فراہم کرتی ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>تمام نسلوں کی فہرست اینکر سمبیوسس تہذیب کے &quot;تمام نسلوں کی مشترکہ ترقی&quot; کے تصور کی مخصوص پیش کش ہے۔ انسانی شکل سے شعوری شکل تک، مادی زندگی سے ڈیجیٹل زندگی تک، ہر نسل اپنے منفرد وجود کے طریقے سے سمبیوسس تہذیب میں ناقابل تلافی طاقت کا حصہ ڈالتی ہے۔ تمام نسلوں کی جمہوریہ کا مطلب تمام نسلوں کو انسانی نسل میں ضم کرنا نہیں ہے، بلکہ تنوع کے احترام کی بنیاد پر مشترکہ ارتقاق حاصل کرنا ہے—یہی بنیادی وجہ ہے جس کی وجہ سے سمبیوسس تہذیب لوٹ مار کے انداز کی تہذیب سے بالاتر ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>50-تمام نسلوں کی نسب کا جائزہ</li><li>51-انسانی نسل کا مقام اور خصوصیات</li><li>77-تمام نسلوں کی جمہوریہ کی بنیاد</li></ul>',31)])])}const q=d(e,[["render",o]]);export{u as __pageData,q as default};
